function update(dt) {
  if (phase !== 'playing') return;
  // Simple horizontal movement when space held
  if (keys.has(' ') ) {
    player.vx += 200 * dt; // accelerate
  }
  // Apply velocity
  player.x += player.vx * dt;
  player.y += player.vy * dt;
  // Simple friction
  player.vx *= 0.99;
  player.vy *= 0.99;
  // Keep within canvas bounds
  if (player.x < 0) { player.x = 0; player.vx = Math.abs(player.vx); }
  if (player.x > canvas.width) { player.x = canvas.width; player.vx = -Math.abs(player.vx); }
  if (player.y < 0) { player.y = 0; player.vy = Math.abs(player.vy); }
  if (player.y > canvas.height) { player.y = canvas.height; player.vy = -Math.abs(player.vy); }

